// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 warpTime, uint256 blockNum, address sender) public {
        vm.assume(sender != address(0) && sender != address(c));
        vm.assume(warpTime > 0);
        vm.assume(value <= address(this).balance);
        vm.warp(warpTime);
        vm.roll(blockNum);
        vm.deal(sender, value);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: value}("");
        assertTrue(ok ? address(c).balance % 10 ether == 0 : true);
    }
}
